# Exercises conversions between float, int, and str.
print(int(3.99))
print(int(-3.99))
print(int(3.0))
print(float(5))
print(float(-5))
print(float("3.14"))
print(float("  2.5  "))
print(str(1.0))
print(str(1.5))
print(str(100.0))
print(str(0.0001))
print(str(-0.0))
